// Answer Discriminated by `type` (§7).
type Answer struct {
	union json.RawMessage
}

// Assignment defines model for Assignment.
type Assignment struct {
	// DurationMinutes Server-enforced. An attempt's deadline is
	// `min(startedAt + duration, closesAt)`, so starting late does not buy
	// a full duration and does not cut the student off mid-window (O-05).
	DurationMinutes int  `json:"durationMinutes"`
	FlaggedCount    *int `json:"flaggedCount,omitempty"`

	// Id uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	Id Uuid `json:"id"`

	// Integrity Defaults are §10.3's, conservative on purpose — the teacher opts into
	// stricter modes per test. Whatever is enabled is stated in plain
	// Vietnamese on the intro page before the student starts (§10.2).
	Integrity   IntegrityPolicy `json:"integrity"`
	MaxAttempts int             `json:"maxAttempts"`

	// PendingGradingCount Handed-in attempts with a manual answer still unmarked (G-09's "Chờ chấm").
	PendingGradingCount *int `json:"pendingGradingCount,omitempty"`

	// PendingManualCount Outstanding manual answers across handed-in attempts, including partially graded papers.
	PendingManualCount *int `json:"pendingManualCount,omitempty"`

	// PublishedAt Null while the assignment is a draft.
	PublishedAt      *time.Time   `json:"publishedAt"`
	Review           ReviewPolicy `json:"review"`
	ShuffleOptions   bool         `json:"shuffleOptions"`
	ShuffleQuestions bool         `json:"shuffleQuestions"`

	// Status **Derived**, never stored (D-18). A pure function of `publishedAt`,
	// `opensAt`, `closesAt` and an optional early `closedAt`, so it cannot go
	// stale and needs no scheduler.
	//
	// `draft` is what an unpublished assignment reads as. It does not weaken
	// D-18: publishing is an explicit act by the teacher, not a timestamp
	// arriving, so nothing has to flip a row on a schedule. A draft is
	// invisible to students and counts towards nothing.
	Status AssignmentStatus `json:"status"`

	// SubmittedCount Distinct enabled students with at least one handed-in non-voided attempt.
	SubmittedCount *int `json:"submittedCount,omitempty"`
	TargetCount    *int `json:"targetCount,omitempty"`
	Targets        struct {
		// Classes The classes this assignment targets, with their names and live member counts.
		Classes []struct {
			// Id uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
			//
			// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
			Id           Uuid   `json:"id"`
			Name         string `json:"name"`
			StudentCount int    `json:"studentCount"`
		} `json:"classes"`

		// Students The students targeted by name, with their names (G-09's chips).
		Students []struct {
			// Id uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
			//
			// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
			Id   Uuid   `json:"id"`
			Name string `json:"name"`
		} `json:"students"`
	} `json:"targets"`

	// TestId uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	TestId      Uuid   `json:"testId"`
	TestTitle   string `json:"testTitle"`
	TestVersion int    `json:"testVersion"`

	// TestVersionId uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	TestVersionId Uuid `json:"testVersionId"`

	// UpdatedAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
	UpdatedAt Timestamp `json:"updatedAt"`
	Window    struct {
		// ClosedAt Set when closed early by the admin.
		ClosedAt *time.Time `json:"closedAt,omitempty"`

		// ClosesAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
		ClosesAt Timestamp `json:"closesAt"`

		// OpensAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
		OpensAt Timestamp `json:"opensAt"`
	} `json:"window"`
}

// AssignmentInput defines model for AssignmentInput.
type AssignmentInput struct {
	// CloseNow PATCH only. Sets `closedAt`, closing the assignment before `closesAt`.
	CloseNow *bool `json:"closeNow,omitempty"`

	// Draft Save without giving it out — G-01's "Lưu nháp". Saving again with
	// `false` publishes it, which is what the "Giao bài" button sends.
	//
	// A draft is the only assignment allowed to have no targets: the point
	// of saving one is to come back to it.
	Draft           *bool `json:"draft,omitempty"`
	DurationMinutes int   `json:"durationMinutes"`

	// Integrity Defaults are §10.3's, conservative on purpose — the teacher opts into
	// stricter modes per test. Whatever is enabled is stated in plain
	// Vietnamese on the intro page before the student starts (§10.2).
	Integrity   IntegrityPolicy `json:"integrity"`
	MaxAttempts int             `json:"maxAttempts"`
	Review      ReviewPolicy    `json:"review"`

	// ShuffleOptions Rejected with VALIDATION_FAILED on shuffleOptions when the selected version contains a group member with fixed option-label dependencies.
	ShuffleOptions *bool `json:"shuffleOptions,omitempty"`

	// ShuffleQuestions Shuffle standalone questions and complete groups as units inside each section; preserve member order.
	ShuffleQuestions *bool `json:"shuffleQuestions,omitempty"`
	Targets          struct {
		ClassIds   []Uuid `json:"classIds"`
		StudentIds []Uuid `json:"studentIds"`
	} `json:"targets"`

	// TestVersionId Must be a published version. Immutable once any attempt exists.
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	TestVersionId Uuid `json:"testVersionId"`
	Window        struct {
		// ClosesAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
		ClosesAt Timestamp `json:"closesAt"`

		// OpensAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
		OpensAt Timestamp `json:"opensAt"`
	} `json:"window"`
}

// AssignmentStatus **Derived**, never stored (D-18). A pure function of `publishedAt`,
// `opensAt`, `closesAt` and an optional early `closedAt`, so it cannot go
// stale and needs no scheduler.
//
// `draft` is what an unpublished assignment reads as. It does not weaken
// D-18: publishing is an explicit act by the teacher, not a timestamp
// arriving, so nothing has to flip a row on a schedule. A draft is
// invisible to students and counts towards nothing.
type AssignmentStatus string

